def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(x, default=(0, 0)):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def nearest(src, items):
        best = None
        best_d = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            d = manhattan(src, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best

    def farthest(src, items):
        best = None
        best_d = None
        for it in items:
            p = pos(it, None)
            if p is None:
                continue
            d = manhattan(src, p)
            if best is None or d > best_d:
                best = p
                best_d = d
        return best

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name", "resource_collection")
    sx, sy = pos(obs.get("self_position", (0, 0)))
    ox, oy = pos(obs.get("opponent_position", (sx, sy)))
    self_p = (sx, sy)
    opp_p = (ox, oy)

    if env == "pursuit_evasion":
        role = obs.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_p, opp_p)
        w = obs.get("grid_width", 0) or 0
        h = obs.get("grid_height", 0) or 0
        corners = []
        if w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        if corners:
            target = farthest(opp_p, corners)
            return step_toward(self_p, target)
        return step_away(self_p, opp_p)

    if env == "territory_control":
        targets = obs.get("unclaimed_cells") or obs.get("opponent_territory") or obs.get("frontier") or []
        target = nearest(self_p, targets)
        if target is not None:
            return step_toward(self_p, target)
        opp_terr = obs.get("opponent_territory") or []
        target = nearest(self_p, opp_terr)
        if target is not None:
            return step_toward(self_p, target)
        return step_away(self_p, opp_p)

    resources = obs.get("resources") or obs.get("resource_positions") or obs.get("resource_cells") or []
    target = nearest(self_p, resources)
    if target is not None:
        return step_toward(self_p, target)

    # Conservative fallback: drift toward opponent in unknown layouts, but avoid zero-lock.
    if sx == ox and sy == oy:
        return [1, 0]
    return step_toward(self_p, opp_p)

